'use strict';
// Russian interface texts. Keys are the English texts exactly as shown.
// `patterns` translate texts with numbers or names in them.

const plural = (n, one, few, many) => {
  n = Math.abs(+n) % 100;
  const d = n % 10;
  if (n > 10 && n < 20) return many;
  if (d === 1) return one;
  if (d >= 2 && d <= 4) return few;
  return many;
};

